<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {api} from './api';
import {locale} from './i18n';
const props=defineProps<{isAdmin:boolean;agents:Array<{id:number;name:string}>}>();
type Policy={windowMinutes:number;authThreshold:number;portThreshold:number;webThreshold:number;notifications:boolean;cooldownMinutes:number;exceptions:Array<{ip:string;agentId:number|null;reason:string;expiresAt:string}>};
const policy=ref<Policy|null>(null),error=ref(''),busy=ref(false),saved=ref(false);
const th=computed(()=>locale.value==='th-TH');
const fields=computed(()=>[{key:'windowMinutes' as const,th:'ช่วงเวลาตรวจ (นาที)',en:'Detection window (minutes)',max:1440,min:1},{key:'authThreshold' as const,th:'จำนวนยืนยันตัวตนผิด',en:'Authentication failures',max:10000,min:2},{key:'portThreshold' as const,th:'จำนวนพอร์ตไม่ซ้ำที่ถูกปฏิเสธ',en:'Distinct denied ports',max:10000,min:2},{key:'webThreshold' as const,th:'จำนวนร้องขอไฟล์สำคัญ',en:'Sensitive path requests',max:10000,min:2},{key:'cooldownMinutes' as const,th:'ช่วงรวมแจ้งเตือน (นาที)',en:'Notification cooldown (minutes)',max:1440,min:1}]);
onMounted(async()=>{try{policy.value=await api<Policy>('/api/threats/policy');}catch(e){error.value=String(e);}});
async function save(){if(!policy.value)return;busy.value=true;error.value='';saved.value=false;try{policy.value=await api<Policy>('/api/threats/policy',{method:'PUT',body:JSON.stringify(policy.value)});saved.value=true;}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
</script>
<template><details class="panel threat-policy"><summary>{{th?'กฎตรวจจับและข้อยกเว้น':'Detection policy and exceptions'}}</summary><p>{{th?'การเปลี่ยนเกณฑ์มีผลกับ Log batch ใหม่ ไม่แก้หลักฐานหรือปิดเคสเก่า ข้อยกเว้นหยุดสร้างเคสใหม่แต่ยังเก็บ Log':'Changes apply on new log batches, without modifying evidence or closing existing cases. Exceptions suppress new detections but retain logs.'}}</p><p v-if="error" role="alert">{{error}}</p><form v-if="policy" @submit.prevent="save" @input="saved=false"><fieldset :disabled="!isAdmin||busy"><div class="fields"><label v-for="field in fields" :key="field.key">{{th?field.th:field.en}}<input v-model.number="policy[field.key]" type="number" :min="field.min" :max="field.max" required></label></div><label class="check"><input v-model="policy.notifications" type="checkbox">{{th?'ส่งแจ้งเตือนเคสใหม่ไปช่องทางที่เปิดใช้งาน':'Send new-case notifications to enabled channels'}}</label><p>{{th?'ส่งเฉพาะหมายเลขเคสแบบรวมกลุ่ม ไม่ส่ง raw Log หากส่งล้มเหลวให้ดูประวัติการแจ้งเตือน ไม่มี retry อัตโนมัติ':'Grouped case IDs only; no raw logs. Review notification delivery history on failure; delivery is not automatically retried.'}}</p><article v-for="(exception,i) in policy.exceptions" :key="i"><div class="fields"><label>IP<input v-model="exception.ip" required></label><label>{{th?'เครื่อง':'Machine'}}<select v-model="exception.agentId"><option :value="null">{{th?'ทุกเครื่อง':'All machines'}}</option><option v-for="a in agents" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>{{th?'เหตุผล (อย่างน้อย 10 ตัวอักษร)':'Reason (at least 10 characters)'}}<input v-model="exception.reason" minlength="10" maxlength="500" required></label><label>{{th?'หมดอายุ (ISO UTC)':'Expires (ISO UTC)'}}<input v-model="exception.expiresAt" placeholder="2026-12-01T00:00:00.000Z" required></label></div><button type="button" class="link" @click="policy.exceptions.splice(i,1)">{{th?'นำข้อยกเว้นออก':'Remove exception'}}</button></article><button v-if="isAdmin" type="button" class="secondary" :disabled="policy.exceptions.length>=100" @click="policy.exceptions.push({ip:'',agentId:null,reason:'',expiresAt:new Date(Date.now()+86400000).toISOString()})">{{th?'เพิ่มข้อยกเว้น':'Add exception'}}</button> <button v-if="isAdmin" class="primary">{{th?'บันทึกกฎ':'Save policy'}}</button></fieldset><p v-if="saved" role="status">{{th?'บันทึกกฎแล้ว':'Policy saved'}}</p></form></details></template>
<style scoped>.threat-policy{padding:20px;margin-bottom:20px}.threat-policy summary{cursor:pointer;font-weight:600}.threat-policy p{font-size:13px;line-height:1.7;color:#b0c1d5}.threat-policy fieldset{border:0;padding:0;min-width:0}.fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.check{display:flex;gap:10px;align-items:center;margin-top:18px}.check input{width:auto}.threat-policy article{padding:15px 0;border-top:1px solid #344258}@media(max-width:700px){.fields{grid-template-columns:1fr}}</style>
